      ["psychokinetic powers. This POKéMON is\nknown to meditate for a whole month\nwithout eating."] = { { 3906946, 79 } },
      ["quickly respond to a threat from any\ndirection with a glare from its upraised\nhead."] = { { 3853389, 74 } },
      ["rare occasions, there will be examples\nof this POKéMON possessing different\nsets of brains."] = { { 3865117, 98 } },
      ["respect from its peers by composing\nmore complex designs in the sky."] = { { 3907960, 47 } },
      ["results in a terribly powerful poison\ngas. The higher the temperature, the\nmore gas is concocted by this POKéMON."] = { { 3869781, 117 } },
      ["return to their quiet mountain retreats\nand go to sleep nestled up against each\nother."] = { { 3855765, 70 } },
      ["said to awaken and wander about in\nsearch of prey."] = { { 3892692, 36 } },
      ["sea to scoop up food, then swallows\neverything in one big gulp."] = { { 3901567, 82 } },
      ["serious, its fiery manes flare and blaze\nas it gallops its way up to 150 mph."] = { { 3863908, 84 } },
      ["shake the ground as if lightning bolts\nhad come crashing down."] = { { 3895058, 47 } },
      ["shell, it is sure evidence that this\nPOKéMON is getting close to evolution."] = { { 3917611, 106 } },
      ["sleep, so it can keep watch over its\nsurroundings 24 hours a day."] = { { 3887588, 106 } },
      ["sleeps, this POKéMON will never fight -\nit will just move away somewhere else."] = { { 3905570, 60 } },
      ["small-bodied POKéMON.\nWhen enraged, it releases a horrible\ntoxin from its horn."] = { { 3854587, 105 } },
      ["stricken by lightning bolts.\nSome towns use ELECTABUZZ in place of\nlightning rods."] = { { 3872999, 102 } },
      ["striking beauty of the feathers on its\nhead, compelling them to choose PIDGEOT\nas their POKéMON."] = { { 3852462, 86 } },
      ["stumbling and falling to keep up with\nits parent."] = { { 3863691, 109 } },
      ["such an event because it goes into\nan altered state that is much like\ndeep sleep."] = { { 3859258, 113 } },
      ["that gather around streetlights,\nattracted by the light in the darkness."] = { { 3858334, 41 } },
      ["that it melts anything. However, it\nnever turns its fiery breath on any\nopponent weaker than itself."] = { { 3850392, 61 } },
      ["that this POKéMON slakes its thirst by\ndrinking rainwater that collects on its\nsilk."] = { { 3899177, 109 } },
      ["the air around it becomes distorted,\ncreating mirages of nonexistent\nscenery."] = { { 3901895, 105 } },
      ["the cover of dead grass.\nThis POKéMON occasionally roots out\nhot springs."] = { { 3890773, 76 } },
      ["the foe flinch by jabbing it with its\nspines. It then leaps at the stunned\nfoe to tear wildly with its sharp claws."] = { { 3854373, 114 } },
      ["the more brightly the lightbulb at the\ntip of its tail grows."] = { { 3883067, 67 } },
      ["the object's aroma and texture to\ndetermine whether it likes the object\nor not."] = { { 3917212, 98 } },
      ["the temperature. For that reason, this\nPOKéMON is sometimes used as a\nthermometer."] = { { 3884736, 81 } },
      ["the world in a quest to master all\nkinds of martial arts."] = { { 3861470, 50 } },
      ["they are more useful for generating\nultrasonic waves by vibrating."] = { { 3910611, 79 } },
      ["things by texture and by taste.\nIt is somewhat put off by sour things."] = { { 3869618, 50 } },
      ["this POKéMON begins swinging its arms\nin circles to recharge itself."] = { { 3894306, 61 } },
      ["this POKéMON grows cheerful and joyous\nin the same way."] = { { 3901762, 27 } },
      ["this POKéMON to send signals back and\nforth with others far away."] = { { 3883437, 100 } },
      ["this POKéMON's feet are thought to\nchange shape and become similar to\nthe roots of trees."] = { { 3857265, 76 } },
      ["this POKéMON's light rising from the\ndepths where it swims. It gives the sea\nan appearance of a starlit night."] = { { 3881647, 114 } },
      ["this, it is said that some towns warn\npeople to keep this POKéMON inside\na POKé BALL."] = { { 3864711, 106 } },
      ["those TRAINERS that it recognizes to\npossess superior skill."] = { { 3898404, 35 } },
      ["tightens all its muscles, its body\nbecomes as hard as a rock."] = { { 3904816, 51 } },
      ["to be a curious substance that is not\nof this earth."] = { { 3920224, 55 } },
      ["to catch a fleeing GROVYLE however\nfast they may be."] = { { 3896784, 43 } },
      ["topping 60 mph, it has to come to a\nscreeching halt before it can turn."] = { { 3898744, 96 } },
      ["toxic quills all at once from all over\nits body. It finds swimming somewhat\nchallenging."] = { { 3889076, 82 } },
      ["trains very rigorously. By living that\nway, this POKéMON packs its body with\nenergy."] = { { 3904638, 70 } },
      ["tree branch with its rear legs that\nserve as wings."] = { { 3881288, 90 } },
      ["under its massive body. It then eats\nthe helpless victim using the large \nmouth on its stomach."] = { { 3919682, 66 } },
      ["under the eaves of old houses, sleeping\nwhile hanging upside down."] = { { 3856892, 52 } },
      ["various UNOWN. Research into this\ntopic is ongoing but nothing is known."] = { { 3887152, 114 } },
      ["weakens the prey by dosing it with a\nharsh toxin. It can catch up to 80\nprey at the same time."] = { { 3862849, 103 } },
      ["were all unearthed from different\nlocations."] = { { 3919861, 43 } },
      ["when a POKé BALL was exposed to a\npowerful pulse of energy."] = { { 3868094, 80 } },
      ["when it encounters cold air while it is\nfloating."] = { { 3884919, 76 } },
      ["which is then stored in this POKéMON's\nfur."] = { { 3907120, 83 } },
      ["with its thick and powerful hind legs to\ncharge at the foe at an incredible\nspeed."] = { { 3879625, 114 } },
      ["with other HOPPIP to prepare against\nbeing blown away."] = { { 3884553, 64 } },
      ["your pillow and trying to eat your dream\nthrough your nostrils."] = { { 3867409, 79 } },
    },
